import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  // Validate issueDate format and is a real date
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Validate SKU exists in catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return fail('UNKNOWN_SKU');
    }

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    }

    invoiceLines.push(newLine);
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(roundCents(line.qty * line.unitPrice));
}

/**
 * Calculate the discount for a single line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineDiscount(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }

  if (!line.discountPercent) {
    return ok(0);
  }

  const lineTotalResult = lineTotal(line);
  if (!lineTotalResult.ok) {
    return lineTotalResult;
  }

  const discount = roundCents((lineTotalResult.value * line.discountPercent) / 100);
  return ok(Math.max(0, discount));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  let totalDiscount = 0;
  for (const line of invoice.lines) {
    const lineTotalResult = lineTotal(line);
    if (!lineTotalResult.ok) {
      return fail('LINE_INVALID');
    }
    subtotal += lineTotalResult.value;

    const lineDiscountResult = lineDiscount(line);
    if (!lineDiscountResult.ok) {
      return fail('LINE_INVALID');
    }
    totalDiscount += lineDiscountResult.value;
  }

  subtotal = roundCents(subtotal);
  totalDiscount = roundCents(totalDiscount);
  const total = Math.max(0, roundCents(subtotal - totalDiscount));

  return ok({
    subtotal,
    discount: totalDiscount,
    total,
  });
}

/**
 * Add or increase a line on an invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent if provided
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Validate SKU exists in catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return fail('UNKNOWN_SKU');
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists on invoice
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    // Increase qty of existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }

    newLines.push(newLine);
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new lines without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice, assigning it a number and marking it as issued.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of already-used invoice numbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const issuedInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(issuedInvoice);
}

function isValidDate(dateString) {
  // Check format YYYY-MM-DD
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(dateString)) {
    return false;
  }

  // Parse and check if it's a valid date
  const date = new Date(dateString + 'T00:00:00Z');
  const parts = dateString.split('-');
  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  // Check if date components match (handles invalid dates like 2025-02-30)
  return date.getUTCFullYear() === year &&
         date.getUTCMonth() === month - 1 &&
         date.getUTCDate() === day;
}

