import { test } from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('renderInvoiceText: shows DRAFT for unsent invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText: shows invoice number when issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = invoiceResult.value;

  const issueResult = issueInvoice(invoice, []);
  assert.equal(issueResult.ok, true);
  invoice = issueResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2025-0001');
});

test('renderInvoiceText: includes customer name', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText: shows line items with qty, name, unit price, total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  assert.match(text, /8 × Development \(hour\) @ €95\.00 = €760\.00/);
});

test('renderInvoiceText: formats prices with formatEuros', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-02-14',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // 2 × Logo package at €1,200.00 = €2,400.00
  assert.match(text, /2 × Logo package @ €1,200\.00 = €2,400\.00/);
});

test('renderInvoiceText: shows total line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // C-002 has standard tier (0% discount), so total = €760.00
  assert.match(text, /^Total: €760\.00$/m);
});

test('renderInvoiceText: calculates correct total for multiple lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // C-002 has standard tier (0% discount), so 5 × 95 + 3 × 85 = 475 + 255 = 730.00
  assert.match(text, /^Total: €730\.00$/m);
});

test('renderInvoiceText: shows discount on line item', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // 10 * €95.00 = €950.00, 10% = €95.00
  assert.match(text, /10% off: -€95\.00/);
});

test('renderInvoiceText: shows subtotal and discount lines when discounts present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert(lines.some((l) => l.match(/^Subtotal:/)));
  assert(lines.some((l) => l.match(/^Discount:/)));
});

test('renderInvoiceText: does not show discount line when no discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert(!lines.some((l) => l.match(/^Subtotal:/) || l.match(/^Discount:/) && !l.match(/^Total:/)));
});

test('renderInvoiceText: calculates total correctly with discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 50 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  // Logo pack = 120000 cents, 50% discount = 60000, total = 60000
  assert.match(text, /^Subtotal: €1,200\.00$/m);
  assert.match(text, /^Discount: -€600\.00$/m);
  assert.match(text, /^Total: €600\.00$/m);
});

test('renderInvoiceText: shows all lines in order', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'ICON-SET', qty: 10 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  const lines = text.split('\n');
  assert.equal(lines.length, 6); // DRAFT + customer + 3 lines + total
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.match(lines[2], /Development \(hour\)/);
  assert.match(lines[3], /Design work \(hour\)/);
  assert.match(lines[4], /Icon set/);
  assert.match(lines[5], /^Total:/);
});

test('renderInvoiceText: handles single-character quantity display', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  assert.match(text, /^1 × Development/m);
});

test('renderInvoiceText: handles large quantities', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'STICKER', qty: 500 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const text = renderInvoiceText(invoice);

  assert.match(text, /^500 × Sticker sheet/m);
});

test('renderInvoiceText: handles different customers', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-005',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

